import csv
import io
import re


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    ))

    header_index = None
    first_nonblank = None
    label_pattern = re.compile(r"[^\W\d][\w.\s()/:\-]*")

    for index, record in enumerate(records):
        labels = [field.strip() for field in record]
        if not any(labels):
            continue
        if first_nonblank is None:
            first_nonblank = index

        # The width hint describes the sampled data, not the full header.
        if (
            len(labels) >= 28
            and len({label.casefold() for label in labels}) == len(labels)
            and all(label_pattern.fullmatch(label) for label in labels)
        ):
            header_index = index
            break

    if header_index is None:
        header_index = first_nonblank
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max(len(columns), max((len(row) for row in rows), default=0))

    used_names = {name.casefold() for name in columns}
    extra_number = 1
    while len(columns) < width:
        name = f"extra_{extra_number}"
        extra_number += 1
        if name.casefold() not in used_names:
            columns.append(name)
            used_names.add(name.casefold())

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
